//! Optional pinned reference output. One processor per export, never a default transform.
use crate::{effects::Frame,model::Project};
use std::{process::{Child,Command,Stdio},sync::{mpsc,Arc,Mutex},thread,io::{Read,Write},time::{Duration,Instant}};
pub struct Processor{child:Child,tx:Option<mpsc::SyncSender<Vec<u8>>>,rx:Option<mpsc::Receiver<Result<Vec<u8>,String>>>,threads:Vec<thread::JoinHandle<()>>,w:usize,h:usize,stderr:Arc<Mutex<Vec<u8>>>}
impl Processor{
 pub fn new(p:&Project,w:usize,h:usize,mode:&str)->Result<Self,String>{p.color_pipeline.validate()?;if !p.color_pipeline.enabled||p.color_pipeline.working_gamut!=3{return Err("OCIO reference requires declared scene-linear ACEScg/AP1 working gamut3".into())}if !["sdr","pq2020"].contains(&mode)||w==0||h==0{return Err("invalid reference dimensions/mode".into())}if (w as u128)*(h as u128)>crate::guard::limits().max_pixels as u128{return Err("OCIO frame exceeds canvas pixel limit".into())}let size=w.checked_mul(h).and_then(|n|n.checked_mul(16)).ok_or("OCIO frame overflow")?;crate::guard::reserve(size.checked_mul(4).ok_or("OCIO memory overflow")?);
 let mut child=Command::new("python3").args(["-c",include_str!("ocio_bridge.py"),&w.to_string(),&h.to_string(),mode]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().map_err(|e|e.to_string())?;
 let mut errors=child.stderr.take().ok_or("no OCIO stderr")?;let stderr=Arc::new(Mutex::new(Vec::new()));let sink=stderr.clone();let error_thread=thread::spawn(move||{let mut buf=[0u8;1024];while let Ok(n)=errors.read(&mut buf){if n==0{break}if let Ok(mut s)=sink.lock(){let remaining=8192usize.saturating_sub(s.len());s.extend_from_slice(&buf[..n.min(remaining)]);}}});let mut input=child.stdin.take().ok_or("no OCIO input")?;let mut output=child.stdout.take().ok_or("no OCIO output")?;let(tx,write_rx)=mpsc::sync_channel::<Vec<u8>>(1);let(read_tx,rx)=mpsc::sync_channel(1);
 let writer=thread::spawn(move||{while let Ok(b)=write_rx.recv(){if input.write_all(&b).is_err(){break}}});let reader=thread::spawn(move||loop{let mut b=vec![0;size];if let Err(e)=output.read_exact(&mut b){let _=read_tx.send(Err(format!("OCIO output unavailable ({e}); requires installed python3 + opencolorio==2.5.1")));break}if read_tx.send(Ok(b)).is_err(){break}});
 Ok(Self{child,tx:Some(tx),rx:Some(rx),threads:vec![writer,reader,error_thread],w,h,stderr})
 }
 pub fn apply(&mut self,f:&Frame)->Result<Frame,String>{if f.w!=self.w||f.h!=self.h||f.w.checked_mul(f.h).and_then(|v|v.checked_mul(4))!=Some(f.d.len())||f.d.iter().any(|v|!v.is_finite())||f.d.chunks_exact(4).any(|p|!(0. ..=1.).contains(&p[3])){return Err("invalid OCIO frame".into())}crate::guard::check();let mut bytes=Vec::with_capacity(f.d.len()*4);for v in &f.d{bytes.extend_from_slice(&v.to_le_bytes())}self.tx.as_ref().ok_or("OCIO processor closed")?.try_send(bytes).map_err(|e|format!("OCIO input queue: {e}"))?;
 let deadline=Instant::now()+Duration::from_secs(60);let bytes=loop{crate::guard::check();match self.rx.as_ref().ok_or("OCIO processor closed")?.recv_timeout(Duration::from_millis(100)){Ok(Ok(b))=>break b,Ok(Err(e))=>{self.close();return Err(self.diagnostic(e))},Err(mpsc::RecvTimeoutError::Timeout) if Instant::now()<deadline=>continue,Err(e)=>{self.close();return Err(self.diagnostic(format!("OCIO frame timeout/disconnect: {e}")))}}};let d:Vec<f32>=bytes.chunks_exact(4).map(|b|f32::from_le_bytes(b.try_into().unwrap())).collect();if d.iter().any(|v|!v.is_finite()){return Err("nonfinite OCIO output".into())}Ok(Frame{w:f.w,h:f.h,d})}
fn diagnostic(&self,error:String)->String{let details=self.stderr.lock().ok().map(|v|String::from_utf8_lossy(&v).trim().to_string()).unwrap_or_default();if details.is_empty(){error}else{format!("{error}; processor diagnostic: {details}")}}
 fn close(&mut self){self.tx.take();let _=self.child.kill();let _=self.child.wait();self.rx.take();for handle in self.threads.drain(..){let _=handle.join();}}
}
impl Drop for Processor{fn drop(&mut self){self.close();}}
struct Encoder(Child);
impl Drop for Encoder{fn drop(&mut self){let _=self.0.kill();let _=self.0.wait();}}
pub fn reference(p:&Project,f:&Frame,mode:&str)->Result<Frame,String>{if f.w==0||f.h==0||f.w.checked_mul(f.h).and_then(|n|n.checked_mul(4))!=Some(f.d.len())||f.d.iter().any(|v|!v.is_finite())||f.d.chunks_exact(4).any(|p|!(0. ..=1.).contains(&p[3])){return Err("invalid OCIO frame before processor spawn".into())}Processor::new(p,f.w,f.h,mode)?.apply(f)}
/// Explicit video-only reference export, no audio or project output transform.
pub fn export_sdr_video(p:&Project,path:&str,crf:u32)->Result<f64,String>{if !path.to_lowercase().ends_with(".mp4")||crf>51{return Err("reference video requires .mp4 and CRF0..51".into())}let duration=p.duration();if p.width==0||p.height==0||p.width%2!=0||p.height%2!=0||!p.fps.is_finite()||p.fps<=0.||!duration.is_finite()||duration<0.{return Err("reference MP4 needs even nonzero dimensions, finite positive fps and nonnegative duration".into())}crate::guard::check_project(p,crate::guard::limits())?;let mut processor=Processor::new(p,p.width as usize,p.height as usize,"sdr")?;let n=(duration*p.fps).round() as usize;if n==0{return Err("empty reference timeline".into())}let mut cache=crate::render::Cache::new();let mut encoder=Encoder(Command::new("ffmpeg").args(["-v","error","-y","-f","rawvideo","-pix_fmt","rgba","-s",&format!("{}x{}",p.width,p.height),"-r",&p.fps.to_string(),"-i","-","-c:v","libx264","-crf",&crf.to_string(),"-vf","scale=out_color_matrix=bt709:out_range=tv","-pix_fmt","yuv420p","-color_range","tv","-color_primaries","bt709","-color_trc","iec61966-2-1","-colorspace","bt709",path]).stdin(Stdio::piped()).spawn().map_err(|e|e.to_string())?);let mut input=encoder.0.stdin.take().ok_or("no reference encoder input")?;
 let result=(||{for i in 0..n{crate::guard::check();let t=i as f64/p.fps;crate::render::prepare_at(p,&mut cache,Some(t))?;let f=crate::render::render_frame(p,t,&cache)?;let output=processor.apply(&f)?;input.write_all(&crate::render::to_rgba8(&output)).map_err(|e|e.to_string())?;}Ok::<_,String>(())})();drop(input);if result.is_err(){let _=encoder.0.kill();}let status=encoder.0.wait().map_err(|e|e.to_string())?;result?;if !status.success(){return Err("reference video encoder failed".into())}Ok(n as f64/p.fps)}

#[cfg(test)]mod lifecycle_tests{use super::*;
#[test]fn failed_child_is_not_reused(){if std::env::var("KINO_TEST_OCIO").is_err(){return}let mut p=Project::default();p.color_pipeline.enabled=true;p.color_pipeline.working_gamut=3;let mut c=Processor::new(&p,1,1,"sdr").unwrap();let id=c.child.id();c.child.kill().unwrap();let f=Frame{w:1,h:1,d:vec![0.1,0.2,0.3,1.]};assert!(c.apply(&f).is_err());assert!(c.tx.is_none());assert!(c.apply(&f).is_err());drop(c);assert!(!std::path::Path::new(&format!("/proc/{id}")).exists());}
}
/// Common-domain numeric difference, no quality ranking or certification.
pub fn compare_sdr(p:&Project,f:&Frame)->Result<serde_json::Value,String>{
 let q=&p.color_pipeline;if !q.enabled||q.working_gamut!=3||q.output_gamut!=0||q.output_transfer!=1{return Err("reference comparison needs enabledAP1working and Rec709/sRGBconfiguredoutput".into())}
 let r=reference(p,f,"sdr")?;let mut ours=Frame{w:f.w,h:f.h,d:f.d.clone()};crate::color::pipeline::output(p,&mut ours)?;let mut sum=[0f64;3];let mut maximum=[0f64;3];let mut signed=[0f64;3];let mut n=0usize;let mut bounded=0usize;
 for (i,(a,b)) in ours.d.chunks_exact(4).zip(r.d.chunks_exact(4)).enumerate(){if i%65536==0{crate::guard::check()}if a.iter().chain(b.iter()).any(|v|!v.is_finite())||!(0. ..=1.).contains(&a[3]){return Err("reference comparison requires finiteRGB/alpha0..1".into())}if a[3]==0.{continue}n+=1;if a[..3].iter().any(|v|*v<0.||*v>1.){bounded+=1}for j in 0..3{let delta=a[j] as f64-b[j] as f64;sum[j]+=delta*delta;signed[j]+=delta;maximum[j]=maximum[j].max(delta.abs());}}
 if n==0{return Err("reference comparison needs visiblepixels".into())}let rmse=sum.map(|v|(v/n as f64).sqrt());let bias=signed.map(|v|v/n as f64);
 Ok(serde_json::json!({"domain":"Rec709 primaries, sRGB encoded float RGB before integer clipping","visible_pixels":n,"configured_outside_0_1_pixels":bounded,"rmse_rgb":rmse,"max_abs_delta_rgb":maximum,"mean_signed_delta_rgb":bias,"configured_pipeline":q,"reference_view":"ACES 2.0 - SDR 100 nits (Rec.709)","config":"cg-config-v4.0.0_aces-v2.0_ocio-v2.5","ocio_version":"2.5.1","note":"Different rendering operators intentionally produce different pixels. Error metrics describe difference, not correctness, creative quality, industry parity or ACES certification. Visible pixels unweighted; no effect or output settings changed."}))
}
